create extension if not exists pgcrypto;
create extension if not exists vector;
do $$ begin create type public.scan_status as enum ('queued','running','completed','completed_with_errors','failed'); exception when duplicate_object then null; end $$;
do $$ begin create type public.document_status as enum ('queued','processing','processed','failed'); exception when duplicate_object then null; end $$;
do $$ begin create type public.match_category as enum ('EXACT_DUPLICATE','NEAR_DUPLICATE','SAME_STRUCTURE_DIFFERENT_VALUES','SAME_CONCEPT_SIMILAR','RELATED_BUT_DIFFERENT','NOT_SIMILAR'); exception when duplicate_object then null; end $$;
create table if not exists public.users(id uuid primary key default gen_random_uuid(),email text unique not null,name text,image text,google_subject text unique,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.scan_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users(id) on delete cascade,spreadsheet_id text not null,gid text not null,sheet_url text not null,access_token_hash text,status public.scan_status not null default 'queued',total_documents int not null default 0,processed_documents int not null default 0,total_questions int not null default 0,comparisons_generated int not null default 0,conflicts_count int not null default 0,errors_count int not null default 0,current_step text,created_at timestamptz default now(),started_at timestamptz,completed_at timestamptz);
create table if not exists public.documents(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users(id) on delete cascade,canonical_url text not null,source_url text not null,file_id text,filename text,content_hash text,file_size bigint,storage_path text,status public.document_status not null default 'queued',page_count int,question_count int not null default 0,processing_error text,source_kind text,created_at timestamptz default now(),updated_at timestamptz default now(),unique(user_id,canonical_url));
create table if not exists public.scan_documents(scan_id uuid references public.scan_jobs(id) on delete cascade,document_id uuid references public.documents(id) on delete cascade,ordinal int not null default 0,primary key(scan_id,document_id));
create table if not exists public.questions(id uuid primary key default gen_random_uuid(),document_id uuid references public.documents(id) on delete cascade,question_number text not null,page_number int not null,raw_text text not null,normalized_text text not null,options_json jsonb not null default '[]'::jsonb,answer text,section text,subject text,question_type text,numeric_features jsonb not null default '{}'::jsonb,created_at timestamptz default now(),unique(document_id,question_number,page_number));
create table if not exists public.question_embeddings(question_id uuid primary key references public.questions(id) on delete cascade,embedding vector(1536),provider text not null,model text not null,created_at timestamptz default now());
create index if not exists question_embeddings_hnsw on public.question_embeddings using hnsw(embedding vector_cosine_ops);
create table if not exists public.similarity_matches(id uuid primary key default gen_random_uuid(),scan_id uuid references public.scan_jobs(id) on delete cascade,question_a_id uuid references public.questions(id) on delete cascade,question_b_id uuid references public.questions(id) on delete cascade,lexical_score real not null default 0,semantic_score real not null default 0,numeric_score real not null default 0,structure_score real not null default 0,final_score real not null default 0,category public.match_category not null,confidence real not null default 0,reason text not null,verified_by_llm boolean not null default false,verifier_payload jsonb,created_at timestamptz default now(),unique(scan_id,question_a_id,question_b_id));
create index if not exists similarity_matches_scan_idx on public.similarity_matches(scan_id,final_score desc);
create table if not exists public.processing_errors(id uuid primary key default gen_random_uuid(),scan_id uuid references public.scan_jobs(id) on delete cascade,document_id uuid references public.documents(id) on delete cascade,stage text not null,message text not null,details jsonb,created_at timestamptz default now());
create or replace function public.find_embedding_candidates(p_scan_id uuid,p_question_id uuid,p_limit int default 25,p_threshold float default .55) returns table(question_id uuid,score float) language sql stable as $$ select qe.question_id,1-(qe.embedding <=> target.embedding) from public.question_embeddings qe cross join public.question_embeddings target join public.questions q on q.id=qe.question_id join public.scan_documents sd on sd.document_id=q.document_id and sd.scan_id=p_scan_id where target.question_id=p_question_id and qe.question_id<>p_question_id and qe.embedding is not null and target.embedding is not null and 1-(qe.embedding <=> target.embedding)>=p_threshold order by qe.embedding <=> target.embedding limit p_limit; $$;
